  const basePath = normalizeErrorPath(validationError);
  if (validationError.keyword === 'required') {
    const missingProperty = readStringParam(validationError.params, 'missingProperty') ?? '<unknown>';
    const path = [basePath, missingProperty].filter(Boolean).join('.');
