  }
  return {
    path,
    constraint: validationError.keyword,
    summary: `${path} failed ${validationError.keyword} constraint`,
  };
}

function normalizeErrorPath(validationError: RawValidationError): string {
  const rawPath = validationError.instancePath ?? validationError.dataPath ?? '';
  return rawPath.replace(/^[/.]/, '').replaceAll('/', '.');
}

